const $ = s => document.querySelector(s);
const API_ROOT = new URL('api/', window.location.href).pathname.replace(/\/$/,'');
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
 folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2"/>',
 check:'<path d="m5 12 4 4L19 6"/>', plus:'<path d="M12 5v14M5 12h14"/>',
 file:'<path d="M14 3H5v18h14V8Z M14 3v5h5M8 12h8m-8 4h6"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 edit:'<path d="m15 4 5 5M4 20l4-1L21 6l-5-5L3 14l-1 8Z"/>',
 trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c6 4 12 4 18 0M11 13h2"/>',
 signature:'<path d="m4 15 9-10 4 4-9 10-5 1Z M13 5l3-3 4 4-3 3M13 20h8"/>',
 export:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
 logout:'<path d="M9 3H3v18h6m5-15 6 6-6 6m-6-6h12"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 grid:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 3v18M3 15h18"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
 back:'<path d="m14 5-7 7 7 7"/>', reload:'<path d="M20 11a8 8 0 1 0-2 7M20 4v7h-7"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.file}</svg>`;
const btn=(action,label,ico='',extra='',attrs='')=>`<button class="btn ${extra}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${esc(label)}</button>`;
const S={user:null,csrf:'',catalog:{employees:[],positions:[],workTypes:[],permissions:[],signers:[]},sheets:[],users:[],view:'home',sheet:null,week:0,allDays:false,category:'regular',search:'',busy:false,menu:false,occupied:[],workflows:[],workflow:null,planRows:[]};
const modal=$('#modal'),picker=$('#picker');let formHandler=null,confirmResolve=null,pickerState=null,toastTimer;
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',error?6500:3200);}
async function api(path,method='GET',data){const r=await fetch(API_ROOT+path,{method,headers:{...(data!==undefined?{'Content-Type':'application/json'}:{}),...(S.csrf?{'X-CSRF-Token':S.csrf}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})});const body=await r.json();if(!r.ok){if(r.status===401&&S.user){S.user=null;renderAuth(false);}const e=new Error(body.error||'Не удалось выполнить действие');e.status=r.status;throw e;}return body;}
const accessLabels={timesheets:'Табели',database:'База данных',planning:'Планирование',verification:'Верификация',control:'Контроль'};
const flowStages=['planning','verification','control'];
const can=key=>S.user?.role==='admin'||(S.user?.access||['timesheets','database']).includes(key);
function canView(view){return ['draft','completed','sheet'].includes(view)?can('timesheets'):['employees','workTypes','signers'].includes(view)?can('database'):flowStages.includes(view)?can(view):view==='users'?S.user?.role==='admin':true;}
async function loadData(){
 [S.catalog,S.sheets,S.workflows]=await Promise.all([can('database')?api('/catalog'):can('timesheets')?api('/sheet-catalog'):Promise.resolve({employees:[],positions:[],workTypes:[],permissions:[],signers:[]}),can('timesheets')?api('/sheets'):Promise.resolve([]),api('/workflows')]);
}
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const monthTitle=m=>new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(m+'-01T12:00:00'));
const daysIn=m=>{const[y,n]=m.split('-').map(Number);return new Date(y,n,0).getDate();};
const dateText=d=>d?new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(d)):'—';
const momentText=d=>new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(d));
const shortName=name=>{const[a,...p]=name.trim().split(/\s+/);return a+(p.length?' '+p.map(w=>w[0].toUpperCase()+'.').join(''):'');};
const statusBadge=s=>`<span class="badge ${s}">${s==='draft'?'В работе':'Завершён'}</span>`;
const searchBox=(placeholder='Поиск…')=>`<label class="search">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(S.search)}"></label>`;
function renderAuth(setup,tokenRequired=false){
 $('#app').innerHTML=`<div class="auth-screen"><aside class="auth-aside"><div class="auth-brand-lockup"><img class="auth-logo" src="./favicon.svg" alt="" width="84" height="84"><h1 class="auth-system-title"><span>Табельный</span> <span>учёт</span></h1></div><div class="auth-calendar-art" aria-hidden="true"><div class="auth-art-binding"><i></i><i></i></div><div class="auth-art-line"></div><div class="auth-art-grid">${Array.from({length:28},(_,i)=>`<i class="${[2,3,9,10,15,23].includes(i)?'marked':''}"></i>`).join('')}</div></div><div class="auth-brand-rule" aria-hidden="true"></div></aside><main class="auth-main"><form id="auth-form" class="auth-card"><div class="eyebrow">${setup?'Первый запуск':'Добро пожаловать'}</div><h2 style="margin-top:12px">${setup?'Настройка системы':'Вход в систему'}</h2><p>${setup?'Создайте аккаунт администратора. Он сможет добавлять пользователей и возвращать завершённые табели в работу.':'Введите логин и пароль вашего аккаунта.'}</p>${setup?field('name','Ваше ФИО','text','',true,'Иванов Иван Иванович'):''}${field('username','Логин','text','',true,setup?'Например, admin':'Ваш логин')}${field('password','Пароль','password','',true,setup?'Не менее 10 символов':'Ваш пароль')}${setup&&tokenRequired?field('setupToken','Код первоначальной настройки','password','',true,'Код из консоли сервера'):''}<div class="form-error" id="auth-error" role="alert"></div><button class="btn primary" type="submit">${setup?'Создать администратора':'Войти'}${icon('chevron')}</button></form></main></div>`;
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button[type=submit]');b.disabled=true;try{const r=await api(setup?'/setup':'/login','POST',Object.fromEntries(new FormData(f)));S.user=r.user;S.csrf=r.csrf;await loadData();render();}catch(e){$('#auth-error').textContent=e.message;}finally{b.disabled=false;}});
}
function navButton(view,label,ico,count=null,sub=false){const active=S.view===view||(view==='draft'&&S.view==='sheet'&&S.sheet?.status==='draft')||(view==='completed'&&S.view==='sheet'&&S.sheet?.status==='completed');return `<button class="nav-btn ${active?'active':''} ${sub?'nav-sub':''}" data-action="nav" data-view="${view}">${icon(ico)}<span>${label}</span>${count!==null?`<span class="nav-count">${count}</span>`:''}</button>`;}
function render(){
 if(!canView(S.view))S.view="home";
 if(!S.user)return;
 const draft=S.sheets.filter(s=>s.status==='draft').length,completed=S.sheets.length-draft;
 const titles={home:'Главная',draft:'В работе',completed:'Завершённые',employees:'Сотрудники',workTypes:'Виды работ',signers:'Подписанты',users:'Пользователи',planning:'Планирование',verification:'Верификация',control:'Контроль',workflow:S.workflow?.name||'Общая таблица',sheet:S.sheet?.name||'Табель'};
 const db=['employees','workTypes','signers'].includes(S.view);
 $('#app').innerHTML=`<div class="shell ${S.menu?'menu-open':''}"><aside class="rail"><a class="brand" href="#" data-action="nav" data-view="home"><span class="brand-icon">${icon('calendar')}</span>Табельный учёт</a>${can('timesheets')?btn('new-sheet','Создать табель','plus','rail-create'):''}<nav aria-label="Основная навигация">${navButton('home','Главная','home')}${can('timesheets')?`<div class="nav-title">Табели</div>${navButton('draft','В работе','folder',draft,true)}${navButton('completed','Завершённые','check',completed,true)}`:''}${flowStages.filter(can).length?'<div class="nav-title">Согласование</div>':''}${flowStages.filter(can).map(key=>navButton(key,accessLabels[key],'grid',S.workflows.filter(x=>x.stage===key||(key==='control'&&x.stage==='approved')).length,true)).join('')}${can('database')?`<div class="nav-title">База данных</div>${navButton('employees','Сотрудники','users',S.catalog.employees.length,true)}${navButton('workTypes','Виды работ','grid',null,true)}${navButton('signers','Подписанты','signature',S.catalog.signers.length,true)}`:''}</nav><div class="rail-spacer"></div>${S.user.role==='admin'?navButton('users','Пользователи','lock'):''}<div class="rail-divider"></div><div class="profile"><span class="avatar">${esc(initials(S.user.name))}</span><div class="profile-info"><div class="profile-name" title="${esc(S.user.name)}">${esc(S.user.name)}</div><div class="profile-role">${S.user.role==='admin'?'Администратор':'Сотрудник'}</div></div><button class="logout" data-action="logout" title="Выйти" aria-label="Выйти">${icon('logout')}</button></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumb"><button data-action="nav" data-view="home">Табельный учёт</button><span>/</span>${db?'<span>База данных</span><span>/</span>':''}<span>${esc(titles[S.view])}</span></div><div class="right"><span class="dot"></span>${new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</div></header><div id="page"></div></main></div>`;
 renderPage();
}
function renderPage(){const p=$('#page');if(!p)return;if(S.view==='home')p.innerHTML=homePage();else if(S.view==='draft'||S.view==='completed')p.innerHTML=sheetsPage();else if(S.view==='employees')p.innerHTML=employeesPage();else if(S.view==='signers')p.innerHTML=signersPage();else if(S.view==='workTypes')p.innerHTML=workTypesPage();else if(S.view==='users')p.innerHTML=usersPage();else if(S.view==='sheet')p.innerHTML=sheetPage();else if(flowStages.includes(S.view))p.innerHTML=workflowListPage();else if(S.view==='workflow')p.innerHTML=workflowPage();bindSearch();}
function titlebar(title,description,actions=''){return `<div class="titlebar"><div><h1>${esc(title)}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function folder(view,name,desc,ico,count,tone=''){return `<button class="folder-row" data-action="nav" data-view="${view}"><span class="folder-icon ${tone}">${icon(ico)}</span><span><span class="folder-title">${name}</span><span class="folder-description" style="display:block">${desc}</span></span><span class="folder-meta">${count}</span><span class="folder-arrow">${icon('chevron')}</span></button>`;}
function homePage(){const draft=S.sheets.filter(s=>s.status==='draft').length,done=S.sheets.length-draft;return titlebar('Главная','Табели и справочники вашей команды')+`<div class="home-grid">${can('timesheets')?`<section class="panel"><div class="panel-head"><h2>Табели <span class="count-pill">${S.sheets.length}</span></h2>${icon('folder')}</div><div class="folder-list">${folder('draft','В работе','Табели, которые вы заполняете','folder',`${draft} таб.`, 'green')}${folder('completed','Завершённые','Готовые табели и архив','check',`${done} таб.`, 'blue')}</div><div class="home-note">Новый табель появляется в работе. После заполнения его можно завершить и выгрузить в Excel.</div></section>`:''}${can('database')?`<section class="panel"><div class="panel-head"><h2>База данных</h2>${icon('grid')}</div><div class="folder-list">${folder('employees','Сотрудники','ФИО, должности и сведения','users',S.catalog.employees.length)}${folder('workTypes','Виды работ','Обычные работы и командировки','briefcase',S.catalog.workTypes.length)}${folder('signers','Подписанты','Кто подписывает табели','signature',S.catalog.signers.length)}</div></section>`:''}${flowStages.filter(can).map(key=>`<section class="panel"><div class="panel-head"><h2>${accessLabels[key]}</h2>${icon('grid')}</div><div class="folder-list">${folder(key,'Открыть этап',key==='planning'?'Создание и заполнение общей таблицы':key==='verification'?'Проверка и редактирование':'Финальное согласование','folder',S.workflows.filter(x=>x.stage===key||(key==='control'&&x.stage==='approved')).length)}</div></section>`).join('')}</div>${!Object.keys(accessLabels).some(can)?empty('Нет доступных разделов','Обратитесь к администратору для назначения доступа.','lock'):''}`;}
function empty(title,description,ico='folder',action=''){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function sheetsTable(items,recent=false){return `<div class="data-wrap"><table class="data-table ${recent?'recent-table':''}"><thead><tr><th>Название табеля</th><th>Период</th><th>Сотрудники</th><th>Состояние</th><th>Изменён</th></tr></thead><tbody>${items.map(s=>`<tr class="clickable-row" data-action="open-sheet" data-id="${s.id}"><td><div class="table-name"><span class="document-icon">${icon('file')}</span><button class="table-link" data-action="open-sheet" data-id="${s.id}"><span class="name">${esc(s.name)}</span><span class="sub" style="display:block">${s.filledDays||0} заполненных дней</span></button></div></td><td>${esc(monthTitle(s.month))}</td><td>${s.employeeCount}</td><td>${statusBadge(s.status)}</td><td class="muted small">${esc(momentText(s.updatedAt))}</td></tr>`).join('')}</tbody></table></div>`;}
function sheetsPage(){const complete=S.view==='completed';let list=S.sheets.filter(s=>s.status===(complete?'completed':'draft'));const q=S.search.toLowerCase();list=list.filter(s=>(s.name+' '+monthTitle(s.month)+' '+s.month).toLowerCase().includes(q));return titlebar(complete?'Завершённые табели':'Табели в работе',complete?'Готовые документы хранятся здесь. Вернуть табель в работу может администратор.':'Выберите табель, чтобы продолжить заполнение.',btn('new-sheet','Создать табель','plus','primary'))+`<section class="panel"><div class="toolbar">${searchBox('Поиск по названию или месяцу')}<span class="month-summary right">${list.length} таб.</span></div>${list.length?sheetsTable(list):empty(S.search?'Ничего не найдено':complete?'Завершённых табелей пока нет':'Табелей в работе пока нет',S.search?'Попробуйте другое название или месяц.':complete?'После завершения табель появится в этом разделе.':'Создайте табель, выберите месяц и добавьте сотрудников.','folder',!complete&&!S.search?btn('new-sheet','Создать табель','plus','primary'):'')}</section>`;}
function employeesPage(){const q=S.search.toLowerCase(),list=S.catalog.employees.filter(e=>(e.name+' '+e.position+' '+e.note).toLowerCase().includes(q));return titlebar('Сотрудники','Должность определяет, какие работы можно выбрать в табеле.',btn('position-form','Добавить должность','plus')+btn('employee-form','Добавить сотрудника','plus','primary'))+`<section class="panel"><div class="toolbar">${searchBox('Поиск сотрудника или должности')}<span class="month-summary right">${list.length} сотрудников</span></div>${list.length?`<div class="data-wrap"><table class="data-table"><thead><tr><th>ФИО</th><th>Должность</th><th>Дата рождения</th><th>Примечание</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td class="name">${esc(e.name)}</td><td>${esc(e.position)}</td><td class="muted">${dateText(e.birthday)}</td><td class="muted">${esc(e.note)||'—'}</td><td><div class="row-actions">${btn('employee-form','','edit','icon',`data-id="${e.id}" title="Редактировать сотрудника" aria-label="Редактировать ${esc(e.name)}"`)}${btn('archive-reference','','trash','icon ghost',`data-kind="employees" data-id="${e.id}" title="Убрать из справочника" aria-label="Убрать ${esc(e.name)}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty(S.search?'Ничего не найдено':'Добавьте сотрудников',S.search?'Измените поисковый запрос.':'Укажите ФИО и должность. Дата рождения и примечание необязательны.','users',!S.search?btn('employee-form','Добавить сотрудника','plus','primary'):'')}<div class="table-footer"><span>Добавляйте должности отдельной кнопкой. При создании сотрудника выбирайте должность из списка.</span></div></section>`;}
function signersPage(){const q=S.search.toLowerCase(),list=S.catalog.signers.filter(e=>(e.name+' '+e.position).toLowerCase().includes(q));return titlebar('Подписанты','Выбираются над табелем и указываются в файле Excel.',btn('signer-form','Добавить подписанта','plus','primary'))+`<section class="panel"><div class="toolbar">${searchBox('Поиск подписанта')}<span class="month-summary right">${list.length} подписантов</span></div>${list.length?`<div class="data-wrap"><table class="data-table"><thead><tr><th>ФИО</th><th>Должность в компании</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td class="name">${esc(e.name)}</td><td>${esc(e.position)}</td><td><div class="row-actions">${btn('signer-form','','edit','icon',`data-id="${e.id}" aria-label="Редактировать ${esc(e.name)}" title="Редактировать"`)}${btn('archive-reference','','trash','icon ghost',`data-kind="signers" data-id="${e.id}" title="Убрать из справочника" aria-label="Убрать ${esc(e.name)}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty(S.search?'Ничего не найдено':'Кто подписывает табели?',S.search?'Попробуйте другой запрос.':'Добавьте ФИО и должность подписанта. В Excel будет предусмотрена строка для подписи.','signature',!S.search?btn('signer-form','Добавить подписанта','plus','primary'):'')}</section>`;}
function workTypesPage(){const types=S.catalog.workTypes.filter(w=>w.category===S.category);return titlebar('Виды работ','Управляйте доступными работами для каждой должности.',btn('work-form','Добавить вид работы','plus','primary'))+`<section class="panel"><div class="matrix-top"><div><div class="segmented"><button class="${S.category==='regular'?'selected':''}" data-action="category" data-value="regular">Виды работ</button><button class="${S.category==='trip'?'selected':''}" data-action="category" data-value="trip">Командировки</button></div><p>Нажмите на ячейку: «+» — работа разрешена, пусто — недоступна.</p></div><span class="month-summary">${S.catalog.positions.length} должн. · ${types.length} работ</span></div>${!S.catalog.positions.length?empty('Сначала добавьте должности','Добавленные должности становятся строками матрицы доступных работ.','users',btn('position-form','Добавить должность','plus')):!types.length?empty('Добавьте виды работ',S.category==='trip'?'Укажите работы, которые сотрудники выполняют в командировках.':'Добавьте первую работу, затем разрешите её нужным должностям.','briefcase',btn('work-form','Добавить вид работы','plus','primary')):`<div class="data-wrap"><table class="data-table matrix"><thead><tr><th class="position-head">Должность</th>${types.map(w=>`<th class="work-head"><div class="work-head-name">${esc(w.label)}</div><div class="work-head-actions"><button data-action="work-form" data-id="${w.id}" title="Редактировать работу" aria-label="Редактировать ${esc(w.label)}">${icon('edit')}</button><button data-action="archive-reference" data-kind="work-types" data-id="${w.id}" title="Убрать работу" aria-label="Убрать ${esc(w.label)}">${icon('trash')}</button></div></th>`).join('')}</tr></thead><tbody>${S.catalog.positions.map(p=>`<tr><td class="position-cell">${esc(p.name)}</td>${types.map(w=>{const allowed=S.catalog.permissions.some(x=>x.positionId===p.id&&x.workTypeId===w.id);return `<td><button class="permission ${allowed?'allowed':''}" data-action="permission" data-position="${p.id}" data-work="${w.id}" data-allowed="${allowed}" aria-pressed="${allowed}" aria-label="${esc(p.name)} — ${esc(w.label)}: ${allowed?'разрешено':'не разрешено'}">${allowed?'+':' '}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`}<div class="notice">${icon('info')}<span>В табеле сотрудник увидит только разрешённые для его должности работы. Изменение справочника не переписывает ранее заполненные ячейки.</span></div></section>`;}
function usersPage(){if(S.user.role!=='admin')return empty('Доступ ограничен','Управлять аккаунтами может только администратор.','lock');return titlebar('Пользователи','Настройка входа и доступа к разделам.',btn('user-form','Добавить пользователя','plus','primary'))+`<section class="panel"><div class="data-wrap"><table class="data-table"><thead><tr><th>Имя / логин</th><th>Роль</th><th>Доступные разделы</th><th>Действия</th></tr></thead><tbody>${S.users.map(u=>`<tr><td>${esc(u.name)}<div class="sub">${esc(u.username)}</div></td><td>${u.role==='admin'?'Администратор':'Сотрудник'}</td><td>${u.role==='admin'?'Все разделы':(u.access||[]).map(k=>esc(accessLabels[k])).join(', ')||'Нет доступа'}</td><td><div class="row-actions">${u.role!=='admin'?btn('user-access','Доступ','','',`data-id="${u.id}"`):''}${u.id!==S.user.id?btn('delete-user','Удалить','trash','danger',`data-id="${u.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div></section>`;}

function sheetPage(){const s=S.sheet;if(!s)return '<div class="loading-page">Открываем табель…</div>';const total=daysIn(s.month),completed=s.status==='completed',filled=s.rows.reduce((n,r)=>n+Object.keys(r.cells).length,0);const start=S.allDays?1:S.week*7+1,end=S.allDays?total:Math.min(start+6,total),days=Array.from({length:end-start+1},(_,i)=>start+i),signers=S.catalog.signers;
 const signerOptions='<option value="">Выберите подписанта</option>'+(s.signerId&&!signers.some(x=>x.id===s.signerId)?`<option value="${s.signerId}" selected>${esc(s.signerSnapshot.name)} · сохранённый</option>`:'')+signers.map(x=>`<option value="${x.id}" ${x.id===s.signerId?'selected':''}>${esc(x.name)}</option>`).join('');
 const table=`<div class="sheet-scroll" id="sheet-scroll"><table class="timesheet"><colgroup><col class="employee-col">${'<col class="work-col"><col class="work-col">'.repeat(days.length)}</colgroup><thead><tr><th rowspan="2" class="employee-col">Сотрудник</th>${days.map(d=>{const date=new Date(`${s.month}-${String(d).padStart(2,'0')}T12:00:00`),weekend=[0,6].includes(date.getDay());return `<th colspan="2" class="day-head ${weekend?'weekend':''}"><span class="day-num">${String(d).padStart(2,'0')}</span><span class="day-weekday">${new Intl.DateTimeFormat('ru-RU',{weekday:'short'}).format(date)}</span></th>`;}).join('')}</tr><tr>${days.map(()=>'<th>Вид<br>работы</th><th class="category-trip">Вид работы<br>командировка</th>').join('')}</tr></thead><tbody>${s.rows.map(row=>`<tr><td class="employee-col"><button class="employee-button" data-action="pick-employee" data-row="${row.id}" ${completed?'disabled':''}><span><span class="name">${esc(row.employeeSnapshot.name)}</span><span class="position" style="display:block">${esc(row.employeeSnapshot.position)}</span></span>${completed?'':icon('down')}</button></td>${days.map(d=>['regular','trip'].map(category=>{const entry=row.cells[String(d)],selected=entry?.category===category,conflict=S.occupied.find(x=>x.employeeId===row.employeeId&&x.day===d),blocked=conflict&&!entry,label=selected?entry.label:entry?'—':blocked?'—':'+';return `<td><button class="cell-btn ${category==='trip'?'trip':''} ${selected?'filled':entry?'dash':blocked?'dash':'empty-cell'}" title="${blocked?esc('Занят в табеле «'+conflict.sheetName+'»'):''}" data-action="pick-work" data-row="${row.id}" data-day="${d}" data-category="${category}" aria-label="${esc(row.employeeSnapshot.name)}, ${d} ${esc(monthTitle(s.month))}, ${category==='trip'?'командировка':'обычная работа'}: ${selected?esc(label):entry?'прочерк':blocked?'занят в другом табеле':'не заполнено'}" ${completed?'disabled':''}>${esc(label)}</button></td>`;}).join('')).join('')}</tr>`).join('')}${!completed?`<tr class="add-row"><td class="employee-col"><button class="add-employee" data-action="pick-employee">${icon('plus')}Выбрать сотрудника</button></td><td colspan="${days.length*2}" class="remaining">${s.rows.length?'Добавьте следующего сотрудника':'Начните с выбора сотрудника из базы данных'}</td></tr>`:''}</tbody></table></div>`;
 return `<div class="titlebar"><div><div class="sheet-heading"><h1>${esc(s.name)}</h1>${statusBadge(s.status)}${!completed?btn('rename-sheet','','edit','icon ghost','aria-label="Переименовать табель" title="Переименовать"'):''}</div><p>${esc(monthTitle(s.month))} · ${total} ${total===31?'день':'дней'} · ${s.rows.length} сотрудников</p></div><div class="actions">${btn('back-sheets','К списку','back')}${btn('export','Excel','export')}${S.user.role==='admin'?btn('delete-sheet','Удалить','trash','danger'):''}${completed?(S.user.role==='admin'?btn('reopen','Вернуть в работу','reload','primary'):''):btn('complete','Завершить табель','check','primary')}</div></div><section class="panel">${completed?`<div class="notice locked">${icon('lock')}<span>Табель завершён ${dateText(s.completedAt)}. ${S.user.role==='admin'?'Для изменений верните его в работу.':'Вернуть его в работу может только администратор.'}</span></div>`:''}<div class="sheet-toolbar"><div class="signer-select"><label for="sheet-signer">Подписант</label><select id="sheet-signer" ${completed?'disabled':''}>${signerOptions}</select>${!completed&&can('database')?btn('signer-form','','plus','icon ghost','title="Добавить подписанта" aria-label="Добавить подписанта"'):''}</div><div class="cell-save">${icon('check')}Изменения сохранены</div></div><div class="toolbar"><div class="segmented"><button data-action="sheet-mode" data-value="week" class="${!S.allDays?'selected':''}">По неделям</button><button data-action="sheet-mode" data-value="month" class="${S.allDays?'selected':''}">Весь месяц</button></div>${!S.allDays?`<div class="week-control">${btn('week-prev','','back','icon',`${S.week===0?'disabled':''} aria-label="Предыдущая неделя"`)}<strong>${start}–${end} ${esc(new Intl.DateTimeFormat('ru-RU',{month:'long'}).format(new Date(s.month+'-01T12:00:00')))}</strong>${btn('week-next','','chevron','icon',`${end===total?'disabled':''} aria-label="Следующая неделя"`)}</div>`:''}<span class="month-summary right">Заполнено ${filled} из ${s.rows.length*total} дней</span></div>${table}<div class="sheet-bottom"><div class="legend"><span><i></i>Обычная работа</span><span><i class="trip"></i>Командировка</span><span><i class="blank"></i>Выходной по календарю</span></div><span class="muted small">Excel всегда содержит весь месяц</span></div></section><details class="panel history"><summary>История изменений</summary><ul>${(s.history||[]).map(h=>`<li><time>${momentText(h.at)}</time><span>${esc(h.user)} · ${esc(h.action)}</span></li>`).join('')}</ul></details>`;
}
function field(name,label,type='text',value='',required=false,placeholder=''){return `<label class="field"><span>${label}${!required?' <span class="optional">необязательно</span>':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}" ${type==='password'?'minlength="10" maxlength="200" autocomplete="new-password"':''} ${type==='text'?'maxlength="150"':''}></label>`;}
function closeModal(){modal.close();if(confirmResolve){confirmResolve(false);confirmResolve=null;}formHandler=null;}
function openForm(title,content,handler,submit='Сохранить',description=''){
 if(modal.open)closeModal();formHandler=handler;
 $('#modal-body').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div>${description?`<p class="modal-description">${esc(description)}</p>`:''}<form id="modal-form" class="form-content">${content}<div id="form-error" class="form-error" role="alert"></div><div class="form-actions">${btn('close-modal','Отмена')}<button type="submit" class="btn primary">${esc(submit)}</button></div></form>`;
 modal.showModal();
 $('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button[type=submit]');submit.disabled=true;try{await formHandler(Object.fromEntries(new FormData(form)));closeModal();}catch(e){$('#form-error').textContent=e.message;}finally{submit.disabled=false;}});
}
function confirmAction(title,message,yes='Подтвердить',danger=false){
 if(picker.open)picker.close();if(modal.open)closeModal();
 return new Promise(resolve=>{confirmResolve=resolve;$('#modal-body').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><p class="modal-description">${esc(message)}</p><div class="form-content"><div class="form-actions">${btn('close-modal','Отмена')}${btn('confirm-yes',yes,'',danger?'danger':'primary')}</div></div>`;modal.showModal();});
}
modal.addEventListener('cancel',()=>{if(confirmResolve){confirmResolve(false);confirmResolve=null;}formHandler=null;});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
picker.addEventListener('click',e=>{if(e.target===picker){const r=picker.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)picker.close();}});
function openPicker(title,subtitle,options,onChoose,footer='',emptyMessage='Нет доступных вариантов.'){pickerState={options,onChoose};$('#picker-body').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-picker" aria-label="Закрыть">${icon('close')}</button></div><div class="picker-subtitle">${esc(subtitle)}</div><div class="picker-search"><input id="picker-search" type="search" placeholder="Поиск…" aria-label="Поиск в списке"></div><div class="picker-options" id="picker-options"></div>${footer?`<div class="picker-footer">${footer}</div>`:''}`;function draw(q=''){const items=options.filter(o=>(o.label+' '+(o.sub||'')).toLowerCase().includes(q.toLowerCase()));$('#picker-options').innerHTML=items.length?items.map(o=>`<button class="option ${o.chosen?'chosen':''}" data-action="choose-option" data-id="${esc(o.id)}"><span>${esc(o.label)}${o.sub?`<small>${esc(o.sub)}</small>`:''}</span>${o.chosen?icon('check'):''}</button>`).join(''):`<div class="picker-empty">${esc(q?'Ничего не найдено':emptyMessage)}</div>`;}draw();$('#picker-search').addEventListener('input',e=>draw(e.target.value));picker.showModal();}
function updateSheet(s){S.sheet=s;const summary={id:s.id,name:s.name,month:s.month,status:s.status,revision:s.revision,createdAt:s.createdAt,updatedAt:s.updatedAt,employeeCount:s.rows.length,filledDays:s.rows.reduce((n,r)=>n+Object.keys(r.cells).length,0),signer:s.signerSnapshot?.name||''};const i=S.sheets.findIndex(x=>x.id===s.id);if(i<0)S.sheets.unshift(summary);else S.sheets[i]=summary;S.sheets.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));const scroll=$('#sheet-scroll'),xy=scroll?{x:scroll.scrollLeft,y:scroll.scrollTop}:null;render();if(xy&&$('#sheet-scroll')){$('#sheet-scroll').scrollLeft=xy.x;$('#sheet-scroll').scrollTop=xy.y;}}
async function sheetMutation(action,method,data={}){if(S.busy)return;S.busy=true;try{const s=await api(`/sheets/${S.sheet.id}${action}` ,method,{...data,expectedRevision:S.sheet.revision});S.occupied=await api('/sheets/'+s.id+'/availability');updateSheet(s);return s;}catch(e){toast(e.message,true);if(e.status===409){const s=await api('/sheets/'+S.sheet.id);S.occupied=await api('/sheets/'+s.id+'/availability');updateSheet(s);}throw e;}finally{S.busy=false;}}
function newSheet(){const t=new Date(),month=`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}`;openForm('Создать табель',field('name','Название табеля','text','',true,'Например, Отдел информационного моделирования')+field('month','Месяц и год','month',month,true),async d=>{const s=await api('/sheets','POST',d);S.view='sheet';S.week=0;S.allDays=false;S.occupied=[];updateSheet(s);location.hash='sheet/'+s.id;toast('Табель создан');},'Создать табель','Количество дней определяется выбранным месяцем, в том числе в високосном году.');}
function positionForm(){
 const items=S.catalog.positions;
 const list='<div class="positions-catalog"><h3>Добавленные должности <span class="count-pill">'+items.length+'</span></h3>'+(items.length?'<ul>'+items.map(p=>'<li>'+esc(p.name)+'</li>').join('')+'</ul>':'<p class="muted small">Пока нет добавленных должностей.</p>')+'</div>';
 openForm('Добавить должность',list+field('name','Новая должность','text','',true,'Например, Инженер'),async d=>{S.catalog=await api('/positions','POST',d);render();toast('Должность добавлена');},'Добавить','Здесь видны все сохранённые должности. Они доступны при создании сотрудников и в матрице работ.');
}
function employeeForm(id){
 const e=S.catalog.employees.find(x=>x.id===id);
 if(!S.catalog.positions.length){toast('Сначала добавьте должность');return positionForm();}
 const position='<label class="field"><span>Должность</span><select name="positionId" required><option value="">Выберите должность</option>'+S.catalog.positions.map(p=>'<option value="'+esc(p.id)+'" '+(p.id===e?.positionId?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select><small>Новые должности добавляются отдельной кнопкой «Добавить должность».</small></label>';
 openForm(e?'Редактировать сотрудника':'Добавить сотрудника',field('name','ФИО','text',e?.name||'',true,'Фамилия Имя Отчество')+position+field('birthday','Дата рождения','date',e?.birthday||'')+'<label class="field"><span>Примечание <span class="optional">необязательно</span></span><textarea name="note" maxlength="500" placeholder="Дополнительная информация">'+esc(e?.note||'')+'</textarea></label>',async d=>{S.catalog=await api('/employees'+(id?'/'+id:''),id?'PUT':'POST',d);render();toast(e?'Сотрудник обновлён':'Сотрудник добавлен');});
}
function signerForm(id){const e=S.catalog.signers.find(x=>x.id===id);openForm(e?'Редактировать подписанта':'Добавить подписанта',field('name','ФИО','text',e?.name||'',true,'Фамилия Имя Отчество')+field('position','Должность в компании','text',e?.position||'',true,'Например, Руководитель отдела'),async d=>{S.catalog=await api('/signers'+(id?'/'+id:''),id?'PUT':'POST',d);render();toast(e?'Подписант обновлён':'Подписант добавлен');});}
function workForm(id){const e=S.catalog.workTypes.find(x=>x.id===id),category=e?.category||S.category;openForm(e?'Редактировать вид работы':'Добавить вид работы',field('label','Название работы','text',e?.label||'',true,'Например, Подготовка заключения')+`<input type="hidden" name="category" value="${category}"><p class="muted small" style="margin-top:15px">${category==='trip'?'Работа в командировке':'Обычная работа'}</p>`,async d=>{S.catalog=await api('/work-types'+(id?'/'+id:''),id?'PUT':'POST',d);render();toast(e?'Работа обновлена':'Работа добавлена. Разрешите её нужным должностям.');},'Сохранить',e?'Ранее заполненные ячейки сохранят своё название работы.':'После добавления отметьте «+» напротив должностей, которым доступна эта работа.');}
function accessFields(selected=[]){return `<fieldset class="access-options"><legend>Доступные разделы</legend>${Object.entries(accessLabels).map(([key,label])=>`<label><input type="checkbox" name="access-${key}" ${selected.includes(key)?'checked':''}>${label}</label>`).join('')}<small>Можно выбрать все, несколько или ни одного. У администратора всегда полный доступ.</small></fieldset>`;}
const accessFromForm=d=>Object.keys(accessLabels).filter(k=>d['access-'+k]);
function userForm(){openForm('Добавить пользователя',field('name','Имя пользователя','text','',true)+field('username','Логин','text','',true)+field('password','Первоначальный пароль','password','',true)+`<label class="field"><span>Роль</span><select name="role"><option value="employee">Сотрудник</option><option value="admin">Администратор</option></select></label>`+accessFields(['timesheets','database']),async d=>{await api('/users','POST',{...d,access:accessFromForm(d)});S.users=await api('/users');render();toast('Пользователь добавлен');});}
function userAccessForm(id){const u=S.users.find(x=>x.id===id);openForm('Доступ: '+u.name,accessFields(u.access),async d=>{await api('/users/'+id,'PATCH',{access:accessFromForm(d)});S.users=await api('/users');render();toast('Доступ обновлён');});}

async function go(view){if(!canView(view))return toast('Нет доступа к разделу',true);if(picker.open)picker.close();S.search='';S.menu=false;S.view=view;if(view==='users')S.users=await api('/users');if(view!=='sheet')location.hash=view;render();}
async function openSheet(id){if(!can('timesheets'))throw new Error('Нет доступа к табелям');S.view='sheet';S.week=0;S.allDays=false;[S.sheet,S.occupied]=await Promise.all([api('/sheets/'+id),api('/sheets/'+id+'/availability')]);location.hash='sheet/'+id;render();}
function pickEmployee(rowId){const sheet=S.sheet;if(sheet.status==='completed')return;const row=sheet.rows.find(r=>r.id===rowId),choices=S.catalog.employees.filter(e=>e.id===row?.employeeId||!sheet.rows.some(r=>r.employeeId===e.id));openPicker(row?'Изменить сотрудника':'Выбрать сотрудника','Сотрудники из базы данных',choices.map(e=>({id:e.id,label:e.name,sub:e.position,chosen:e.id===row?.employeeId})),async id=>{picker.close();if(row?.employeeId===id)return;if(row&&Object.keys(row.cells).length&&!await confirmAction('Заменить сотрудника?','Работы этой строки будут очищены, поскольку у другого сотрудника могут быть другие разрешённые виды работ.','Заменить'))return;await sheetMutation('/rows'+(row?'/'+row.id:''),row?'PATCH':'POST',{employeeId:id,clear:true});},row?btn('delete-row','Удалить строку сотрудника','trash','ghost',`data-row="${row.id}"`):btn('picker-go-employees','Добавить сотрудника в базу','plus','ghost'),S.catalog.employees.length?'Все сотрудники уже добавлены в табель.':'В базе пока нет сотрудников. Добавьте их в разделе «Сотрудники».');}
async function pickWork(rowId,day,category){const s=S.sheet;if(s.status==='completed')return;S.occupied=await api('/sheets/'+s.id+'/availability');const busy=S.occupied.find(x=>x.employeeId===s.rows.find(r=>r.id===rowId)?.employeeId&&x.day===day);updateSheet(s);if(busy&&!s.rows.find(r=>r.id===rowId)?.cells[String(day)])return toast('Этот день уже заполнен в табеле «'+busy.sheetName+'». Сначала очистите его там.',true);const row=s.rows.find(r=>r.id===rowId),employee=S.catalog.employees.find(e=>e.id===row.employeeId),entry=row.cells[String(day)],works=employee?S.catalog.workTypes.filter(w=>w.category===category&&S.catalog.permissions.some(p=>p.positionId===employee.positionId&&p.workTypeId===w.id)):[];openPicker(category==='trip'?'Работа в командировке':'Вид работы',`${shortName(row.employeeSnapshot.name)} · ${day} ${monthTitle(s.month)}`,works.map(w=>({id:w.id,label:w.label,chosen:w.id===entry?.workTypeId})),async id=>{picker.close();if(entry&&entry.category!==category&&!await confirmAction('Изменить вид занятости?','За этот день уже выбрана '+(entry.category==='trip'?'командировка':'обычная работа')+'. Она будет заменена выбранной работой, а в соседней ячейке появится прочерк.','Заменить'))return;await sheetMutation('/cells','PUT',{rowId,day,workTypeId:id});},entry?btn('clear-cell','Очистить этот день','close','ghost',`data-row="${rowId}" data-day="${day}"`):btn('picker-go-works','Настроить доступные работы','grid','ghost'),employee?'Для этой должности пока нет разрешённых работ в выбранной категории. Поставьте «+» в матрице видов работ.':'Сотрудник убран из действующего справочника. Старые записи сохранены, но новые работы выбрать нельзя.');}
function bindSearch(){const input=$('#search');if(!input)return;input.addEventListener('input',e=>{const pos=e.target.selectionStart;S.search=e.target.value;renderPage();const next=$('#search');next.focus();if(next.type==='text')next.setSelectionRange(pos,pos);});}

document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;if(b.tagName==='A')event.preventDefault();const a=b.dataset.action;
 try{
  if(a==='close-modal')return closeModal();
  if(a==='close-picker')return picker.close();
  if(a==='confirm-yes'){const resolve=confirmResolve;confirmResolve=null;modal.close();resolve?.(true);return;}
  if(a==='choose-option'){if(S.busy)return;return await pickerState.onChoose(b.dataset.id);}
  if(a==='menu'){S.menu=!S.menu;$('.shell').classList.toggle('menu-open',S.menu);return;}
  if(a==='nav')return await go(b.dataset.view);
  if(a==='new-sheet')return newSheet();
  if(a==='open-sheet')return await openSheet(b.dataset.id);
  if(a==='back-sheets')return await go(S.sheet.status==='completed'?'completed':'draft');
  if(a==='employee-form')return employeeForm(b.dataset.id);
  if(a==='position-form')return positionForm();
  if(a==='signer-form')return signerForm(b.dataset.id);
  if(a==='work-form')return workForm(b.dataset.id);
  if(a==='user-form')return userForm();
  if(a==='user-access')return userAccessForm(b.dataset.id);
  if(a==='delete-user'){const u=S.users.find(x=>x.id===b.dataset.id);if(await confirmAction('Удалить пользователя?',`Доступ для «${u.name}» будет закрыт, все его сессии завершатся. История действий сохранится.`,'Удалить',true)){await api('/users/'+u.id,'DELETE',{confirmDelete:true});S.users=await api('/users');render();toast('Пользователь удалён');}return;}
  if(a.startsWith('workflow-')&&S.busy)return;
  if(a==='new-workflow')return newWorkflow();
  if(a==='open-workflow')return await openWorkflow(b.dataset.id);
  if(a==='workflow-add'){readPlanRows();S.planRows.push({employee:'',work:'',date:'',note:''});renderPage();return;}
  if(a==='workflow-remove'){readPlanRows();S.planRows.splice(Number(b.dataset.index),1);renderPage();return;}
  if(a==='workflow-save')return await saveWorkflow();
  if(a==='workflow-confirm'){if(!await confirmAction('Подтвердить этап?','Таблица будет сохранена и передана на следующий этап. Редактирование на текущем этапе закроется.','Подтвердить'))return;await saveWorkflow();const previous=S.workflow.stage;await api('/workflows/'+S.workflow.id+'/confirm','POST',{expectedRevision:S.workflow.revision});S.workflow=null;await loadData();await go(previous);toast('Этап подтверждён');return;}
  if(a==='go-employees')return await go('employees');
  if(a==='picker-go-employees'){picker.close();await go('employees');employeeForm();return;}
  if(a==='picker-go-works'){picker.close();return await go('workTypes');}
  if(a==='category'){S.category=b.dataset.value;renderPage();return;}
  if(a==='sheet-mode'){S.allDays=b.dataset.value==='month';renderPage();return;}
  if(a==='week-prev'){S.week=Math.max(0,S.week-1);renderPage();return;}
  if(a==='week-next'){S.week=Math.min(Math.ceil(daysIn(S.sheet.month)/7)-1,S.week+1);renderPage();return;}
  if(a==='pick-employee')return pickEmployee(b.dataset.row);
  if(a==='pick-work')return pickWork(b.dataset.row,Number(b.dataset.day),b.dataset.category);
  if(a==='clear-cell'){picker.close();await sheetMutation('/cells','PUT',{rowId:b.dataset.row,day:Number(b.dataset.day),workTypeId:null});return;}
  if(a==='delete-row'){picker.close();if(await confirmAction('Удалить строку?','Сотрудник и все его работы будут удалены только из этого табеля. В справочнике сотрудник останется.','Удалить строку',true))await sheetMutation('/rows/'+b.dataset.row,'DELETE');return;}
  if(a==='permission'){if(S.busy)return;S.busy=true;b.disabled=true;try{S.catalog=await api('/permissions','PUT',{positionId:b.dataset.position,workTypeId:b.dataset.work,allowed:b.dataset.allowed!=='true'});renderPage();}finally{S.busy=false;b.disabled=false;}return;}
  if(a==='delete-sheet'){
    if(S.user.role!=='admin'||S.busy)return;
    const sheet=S.sheet;
    if(!await confirmAction('Удалить табель?',`Табель «${sheet.name}», все заполненные дни и история изменений будут удалены. Восстановить его через сайт нельзя. Сотрудники и справочники останутся.`,'Удалить',true))return;
    S.busy=true;
    try{await api('/sheets/'+sheet.id,'DELETE',{expectedRevision:sheet.revision,confirmDelete:true});await loadData();S.sheet=null;await go(sheet.status==='completed'?'completed':'draft');toast('Табель удалён навсегда');}
    catch(e){if(e.status===409)await openSheet(sheet.id);throw e;}
    finally{S.busy=false;}return;
  }
  if(a==='rename-sheet'){openForm('Переименовать табель',field('name','Название табеля','text',S.sheet.name,true),d=>sheetMutation('','PATCH',d));return;}
  if(a==='export'){
    const r=await fetch(`${API_ROOT}/sheets/${S.sheet.id}/export`);if(!r.ok){const e=await r.json();throw new Error(e.error||'Не удалось выгрузить файл');}
    const url=URL.createObjectURL(await r.blob()),link=document.createElement('a');link.href=url;link.download=(S.sheet.name+' '+S.sheet.month).replace(/[<>:"/\\|?*]/g,'_')+'.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),15000);toast('Excel выгружен за весь месяц');return;
  }
  if(a==='complete'){
    if(!S.sheet.signerSnapshot)return toast('Выберите подписанта перед завершением',true);
    const filled=S.sheet.rows.reduce((n,r)=>n+Object.keys(r.cells).length,0),total=S.sheet.rows.length*daysIn(S.sheet.month);
    if(await confirmAction('Завершить табель?',`Заполнено ${filled} из ${total} дней. Незаполненные дни останутся пустыми. После завершения редактирование будет закрыто; вернуть табель в работу сможет администратор.`,'Завершить')){await sheetMutation('/complete','POST');toast('Табель перемещён в завершённые');}return;
  }
  if(a==='reopen'){if(await confirmAction('Вернуть табель в работу?','Табель снова станет доступен для редактирования. Ранее выгруженные файлы Excel не изменятся.','Вернуть в работу')){await sheetMutation('/reopen','POST');toast('Табель снова в работе');}return;}
  if(a==='archive-reference'){
    if(await confirmAction('Убрать запись из справочника?','Запись исчезнет из новых списков выбора. Сведения в уже заполненных табелях сохранятся.','Убрать',true)){S.catalog=await api('/'+b.dataset.kind+'/'+b.dataset.id,'DELETE',{});renderPage();toast('Запись убрана из справочника');}return;
  }
  if(a==='logout'){await api('/logout','POST',{});S.user=null;S.csrf='';location.hash='';renderAuth(false);}
 }catch(e){toast(e.message,true);}
});
document.addEventListener('change',async e=>{if(e.target.id==='sheet-signer'){const previous=S.sheet.signerId;try{await sheetMutation('','PATCH',{signerId:e.target.value||null});}catch{e.target.value=previous||'';}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.menu){S.menu=false;$('.shell')?.classList.remove('menu-open');}});
window.addEventListener('hashchange',async()=>{if(!S.user)return;const value=location.hash.slice(1);if(value.startsWith('workflow/')){if(value.slice(9)!==S.workflow?.id||S.view!=='workflow')try{await openWorkflow(value.slice(9));}catch(e){toast(e.message,true);await go('home');}}else if(value.startsWith('sheet/')){const id=value.slice(6);if(id!==S.sheet?.id||S.view!=='sheet')try{await openSheet(id);}catch(e){toast(e.message,true);await go('home');}}else if(['home','draft','completed','employees','workTypes','signers','users',...flowStages].includes(value)&&value!==S.view){try{await go(value);}catch(e){toast(e.message,true);}}});
async function init(){try{const session=await api('/session');if(!session.user)return renderAuth(session.setupRequired,session.setupTokenRequired);S.user=session.user;S.csrf=session.csrf;await loadData();const hash=location.hash.slice(1);if(hash.startsWith('workflow/')){await openWorkflow(hash.slice(9));}else if(hash.startsWith('sheet/')&&can('timesheets')){[S.sheet,S.occupied]=await Promise.all([api('/sheets/'+hash.slice(6)),api('/sheets/'+hash.slice(6)+'/availability')]);S.view='sheet';}else if(['home','draft','completed','employees','workTypes','signers','users',...flowStages].includes(hash)){S.view=hash;if(hash==='users')S.users=await api('/users');}render();}catch(e){$('#app').innerHTML=`<div class="loading-page"><div><h2>Не удалось загрузить приложение</h2><p style="margin-top:15px">${esc(e.message)}</p><p style="margin-top:15px">Обновите страницу и проверьте, запущен ли сервер.</p></div></div>`;}}
function workflowListPage(){const stage=S.view,list=S.workflows.filter(x=>x.stage===stage||(stage==='control'&&x.stage==='approved'));return titlebar(accessLabels[stage],'Общая таблица: планирование → верификация → контроль',stage==='planning'?btn('new-workflow','Создать таблицу','plus','primary'):'')+`<section class="panel"><div class="workflow-steps">${flowStages.map((key,i)=>`<div class="${key===stage?'current':''}"><span>${i+1}</span>${accessLabels[key]}</div>`).join('')}</div>${list.length?`<div class="folder-list">${list.map(w=>`<button class="folder-row" data-action="open-workflow" data-id="${w.id}"><span class="folder-icon green">${icon('grid')}</span><span><span class="folder-title">${esc(w.name)}</span><small class="folder-description" style="display:block">${esc(monthTitle(w.month))} · ${w.rowCount} строк</small></span><span class="folder-meta">${w.stage==='approved'?'Согласовано':'Открыть →'}</span></button>`).join('')}</div>`:empty('Таблиц на этом этапе пока нет',stage==='planning'?'Создайте таблицу и заполните строки.':'После подтверждения предыдущего этапа таблица появится здесь.','grid')}</section>`;}
function workflowPage(){const w=S.workflow;if(!w)return '';const locked=w.stage==='approved';return titlebar(w.name,`${esc(monthTitle(w.month))} · ${locked?'Согласовано':accessLabels[w.stage]}`,btn('nav','К списку','back','',`data-view="${locked?'control':w.stage}"`)+(!locked?btn('workflow-save','Сохранить','check')+btn('workflow-confirm','Подтвердить','chevron','primary'):''))+`<section class="panel"><div class="workflow-steps">${flowStages.map((key,i)=>`<div class="${locked||i<flowStages.indexOf(w.stage)?'passed':key===w.stage?'current':''}"><span>${i+1}</span>${accessLabels[key]}</div>`).join('')}</div><div class="notice">${icon('info')}<span>${locked?'Контроль завершён. Таблица сохранена. Автоматическое создание табелей будет добавлено позже.':'Измените таблицу, сохраните или подтвердите передачу на следующий этап. При подтверждении изменения сохраняются.'}</span></div><div class="data-wrap"><table class="data-table workflow-table"><thead><tr><th>Сотрудник</th><th>Работа / задача</th><th>Дата</th><th>Примечание</th>${!locked?'<th></th>':''}</tr></thead><tbody>${S.planRows.map((r,i)=>`<tr>${['employee','work','date','note'].map(key=>`<td>${locked?esc(r[key]):`<input data-plan-index="${i}" data-plan-field="${key}" aria-label="${({employee:'Сотрудник',work:'Работа',date:'Дата',note:'Примечание'})[key]}, строка ${i+1}" type="${key==='date'?'date':'text'}" maxlength="${key==='employee'?150:500}" value="${esc(r[key])}" ${key==='date'?`min="${w.month}-01" max="${w.month}-${daysIn(w.month)}"`:''}>`}</td>`).join('')}${!locked?`<td>${btn('workflow-remove','','trash','icon ghost',`data-index="${i}" aria-label="Удалить строку ${i+1}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>${!locked?`<div class="panel-head">${btn('workflow-add','Добавить строку','plus')}</div>`:''}</section><details class="panel history"><summary>История согласования</summary><ul>${[...w.history].reverse().map(h=>`<li><time>${momentText(h.at)}</time><span>${esc(h.user)} · ${esc(h.action)}</span></li>`).join('')}</ul></details>`;}
function newWorkflow(){const month=new Date().toISOString().slice(0,7);openForm('Новая общая таблица',field('name','Название таблицы','text','',true)+field('month','Месяц','month',month,true),async d=>{const w=await api('/workflows','POST',d);await loadData();await openWorkflow(w.id);},'Создать');}
async function openWorkflow(id){S.workflow=await api('/workflows/'+id);S.planRows=structuredClone(S.workflow.rows);S.view='workflow';location.hash='workflow/'+id;render();}
function readPlanRows(){document.querySelectorAll('[data-plan-index]').forEach(input=>{S.planRows[Number(input.dataset.planIndex)][input.dataset.planField]=input.value;});}
async function saveWorkflow(){if(S.busy)return;S.busy=true;try{readPlanRows();S.workflow=await api('/workflows/'+S.workflow.id,'PATCH',{rows:S.planRows,expectedRevision:S.workflow.revision});S.planRows=structuredClone(S.workflow.rows);renderPage();toast('Таблица сохранена');}catch(e){if(e.status===409)await openWorkflow(S.workflow.id);throw e;}finally{S.busy=false;}}

init();
